def P0(x, y, z):
    """Calculates P_0(x, y, z) = (x-y)^2 + (y-z)^2 + (x-z)^2"""
    return (x - y)**2 + (y - z)**2 + (x - z)**2

# Test cases (a, d)
test_cases = [
    (0, 1),  # (0, 1, 2)
    (0, 2),  # (0, 2, 4)
    (1, 1),  # (1, 2, 3)
    (1, 2),  # (1, 3, 5)
    (2, 1)   # (2, 3, 4)
]

results = {}
for a, d in test_cases:
    x = a
    y = a + d
    z = a + 2*d
    value = P0(x, y, z)
    # Check divisibility by d^2
    if d != 0:
        power_d_check = value % (d**2) == 0
    else:
        power_d_check = True # Should not happen based on problem statement d != 0

    results[(a, d)] = {
        'value': value,
        'd': d,
        'd_squared': d**2,
        'divisible_by_d_squared': power_d_check
    }

for (a, d), res in results.items():
    print(f"For (a, d) = ({a}, {d}): P_0 = {res['value']}, d^2 = {res['d_squared']}. Divisible by d^2? {res['divisible_by_d_squared']}")
